        for(let row=0;row<3;row++){
          bb(W/2,D-.45,W-.3,.65,y+.62+row*.57,.065,{color:0x972925,gloss:.5});
          for(let k=0;k<Math.max(2,Math.floor(W/.34));k++)bb(.24+k*.34,D-.47,.24,.22,y+.7+row*.57,.31,0xb52326);
        }
