    if(id==='2F'&&n==='그라프')Object.assign(p,{floor:'ssg_apc_oak',wall:0xeae6db,portal:0xd6cec1,trim:0xb09b7c});
    // Gangnam branch photos, The Row (2024), TANNAT (2025) and
